From b06bc812263b65775dbbe51b442110084eae1012 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:35:12 +0100
Subject: [PATCH] xdgshellwindow: allow resizing tooltips like applet popups

Tooltips were never resizable, so a Plasma tooltip asking to be resized
from one of its edges was ignored. They can now be resized like applet
popups, which also keeps them from being maximized or tiled.

BUG: 526187
---
 src/tiles/tile.cpp     | 2 +-
 src/xdgshellwindow.cpp | 6 +++---
 2 files changed, 4 insertions(+), 4 deletions(-)

diff --git a/src/tiles/tile.cpp b/src/tiles/tile.cpp
index b6cf27b20c..9d65692bbf 100644
--- a/src/tiles/tile.cpp
+++ b/src/tiles/tile.cpp
@@ -447,7 +447,7 @@ void Tile::resizeByPixels(qreal delta, Qt::Edge edge)

 bool Tile::manage(Window *window)
 {
-    if (!window->isResizable() || window->isAppletPopup()) {
+    if (!window->isResizable() || window->isAppletPopup() || window->isTooltip()) {
         return false;
     }

diff --git a/src/xdgshellwindow.cpp b/src/xdgshellwindow.cpp
index 6f3b1b8d0e..9a9b78c756 100644
--- a/src/xdgshellwindow.cpp
+++ b/src/xdgshellwindow.cpp
@@ -457,7 +457,7 @@ bool XdgToplevelWindow::isResizable() const
     if (isRequestedFullScreen()) {
         return false;
     }
-    if (isSpecialWindow() && !isAppletPopup()) {
+    if (isSpecialWindow() && !isAppletPopup() && !isTooltip()) {
         return false;
     }
     if (rules()->checkSize(QSize()).isValid()) {
@@ -483,7 +483,7 @@ bool XdgToplevelWindow::isFullScreenable() const

 bool XdgToplevelWindow::isMaximizable() const
 {
-    if (!isResizable() || isAppletPopup()) {
+    if (!isResizable() || isAppletPopup() || isTooltip()) {
         return false;
     }
     if (rules()->checkMaximize(MaximizeRestore) != MaximizeRestore || rules()->checkMaximize(MaximizeFull) != MaximizeFull) {
@@ -1740,7 +1740,7 @@ void XdgToplevelWindow::maximize(MaximizeMode mode, const RectF &restore)
         return;
     }

-    if (!isResizable() || isAppletPopup()) {
+    if (!isResizable() || isAppletPopup() || isTooltip()) {
         return;
     }

-- 
