 src/plasmaquick/windowresizehandler.cpp       | 28 +++++++++-
 src/plasmaquick/windowresizehandler.h         |  6 +++
 6 files changed, 178 insertions(+), 4 deletions(-)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..0fd59cf3c 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -33,6 +33,8 @@ ToolTipArea::ToolTipArea(QQuickItem *parent)
     , m_active(true)
     , m_interactive(false)
     , m_hideOnClick(true)
+    , m_resizable(false)
+    , m_resizing(false)
     , m_timeout(-1)
     , m_usingDialog(false)
 {
@@ -144,12 +146,14 @@ void ToolTipArea::showToolTip()
     }

     connect(dlg, &ToolTipDialog::visibleChanged, this, &ToolTipArea::toolTipVisibleChanged, Qt::UniqueConnection);
+    connect(dlg, &ToolTipDialog::resizingChanged, this, &ToolTipArea::updateResizing, Qt::UniqueConnection);

     dlg->setHideTimeout(m_timeout);
     dlg->setOwner(this);
     dlg->setVisualParent(this);
     dlg->setMainItem(mainItem());
     dlg->setInteractive(m_interactive);
+    dlg->setResizable(m_resizable);

     switch (location) {
     case Plasma::Types::Floating:
@@ -285,6 +289,42 @@ void ToolTipArea::setHideOnClick(bool hideOnClick)
     Q_EMIT hideOnClickChanged();
 }

+void ToolTipArea::setResizable(bool resizable)
+{
+    if (m_resizable == resizable) {
+        return;
+    }
+
+    m_resizable = resizable;
+    if (s_dialog && s_dialog->owner() == this) {
+        s_dialog->setResizable(resizable);
+    }
+
+    Q_EMIT resizableChanged();
+}
+
+bool ToolTipArea::resizing() const
+{
+    return m_resizing;
+}
+
+void ToolTipArea::updateResizing()
+{
+    const bool resizing = s_dialog->isResizing() && s_dialog->owner() == this;
+    if (m_resizing == resizing) {
+        return;
+    }
+
+    m_resizing = resizing;
+    const QSizeF size = s_dialog->mainItem() ? s_dialog->mainItem()->size() : QSizeF();
+    if (resizing) {
+        m_sizeBeforeResize = size;
+    } else if (size != m_sizeBeforeResize) {
+        Q_EMIT resized(size);
+    }
+    Q_EMIT resizingChanged();
+}
+
 void ToolTipArea::setTimeout(int timeout)
 {
     m_timeout = timeout;
