 {
+    // While the user resizes the tooltip, its main item gets the size they choose
+    if (m_resizeHandler->isResizing()) {
+        return;
+    }
     QScreen *s = screen();
-    if (!s) {
+    if (!s || !mainItem()) {
         return;
     }
     QSize popupSize = QSize(mainItem()->implicitWidth(), mainItem()->implicitHeight());
@@ -94,13 +117,18 @@ void ToolTipDialog::hideEvent(QHideEvent *event)
 bool ToolTipDialog::event(QEvent *e)
 {
     if (e->type() == QEvent::Enter) {
+        m_containsPointer = true;
         if (m_interactive) {
             m_hideTimer.stop();
         } else {
             setVisible(false);
         }
     } else if (e->type() == QEvent::Leave) {
-        dismiss();
+        m_containsPointer = false;
+        // The pointer leaves the tooltip while the user resizes it
+        if (!m_resizeHandler->isResizing()) {
+            dismiss();
+        }
     }

     return PopupPlasmaWindow::event(e);
@@ -140,6 +168,28 @@ void ToolTipDialog::setInteractive(bool interactive)
     m_interactive = interactive;
 }

+bool ToolTipDialog::resizable() const
+{
+    return m_resizable;
+}
+
+void ToolTipDialog::setResizable(bool resizable)
+{
+    m_resizable = resizable;
+    updateResizeEdges();
+}
+
+bool ToolTipDialog::isResizing() const
+{
+    return m_resizeHandler->isResizing();
+}
