+void ToolTipDialog::updateResizeEdges()
+{
+    // Like applet popups, the edges facing the panel or the screen edge can't be dragged
+    m_resizeHandler->setActiveEdges(m_resizable ? ~nearbyBorders() : Qt::Edges());
+}
+
