From a30fc9af457fea0506d11da00e7fba4f146b3f5f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:56:53 +0100
Subject: [PATCH] applets/taskmanager: make thumbnail tooltips resizable from
 their edges

Window thumbnails in task tooltips had a fixed size, too small to see
much on many screens. Thumbnail tooltips can now be resized by dragging
their free edges like Kickoff and the system tray, and the size is kept.

BUG: 526187
---
 applets/taskmanager/main.xml                |  8 ++++
 applets/taskmanager/qml/Task.qml            |  1 +
 applets/taskmanager/qml/ToolTipDelegate.qml | 52 ++++++++++++++++++++-
 applets/taskmanager/qml/ToolTipInstance.qml |  2 +-
 4 files changed, 60 insertions(+), 3 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..e34800352f 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -75,6 +75,14 @@
       <label>Whether to show tooltips when hovering task buttons.</label>
       <default>true</default>
     </entry>
+    <entry name="toolTipWidth" type="Int">
+      <label>The width of each window in tooltips with window thumbnails, set by dragging the tooltip's edges. 0 means the default width.</label>
+      <default>0</default>
+    </entry>
+    <entry name="toolTipThumbnailHeight" type="Int">
+      <label>The height of window thumbnails in tooltips, set by dragging the tooltip's edges. 0 means the default height.</label>
+      <default>0</default>
+    </entry>
     <entry name="taskMaxWidth" type="Enum">
       <label>Tune the max width of task items.</label>
       <choices>
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..817f095ebf 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -82,6 +82,7 @@ PlasmaCore.ToolTipArea {
     active: !inPopup && !tasksRoot.groupDialog && task.contextMenu?.status !== PlasmaExtras.Menu.Open && task === (tasksRoot.toolTipOpenedByClick ?? task)
     interactive: model.IsWindow || mainItem.playerData
     hideOnClick: !(hasAudioStream && audioIndicatorsEnabled)
+    resizable: Plasmoid.configuration.showToolTips && model.IsWindow
     location: Plasmoid.location
     mainItem: !Plasmoid.configuration.showToolTips || !model.IsWindow ? pinnedAppToolTipDelegate : openWindowToolTipDelegate

diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..6789b58221 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -53,8 +53,23 @@ Loader {
     property bool blockingUpdates: false

     readonly property bool isVerticalPanel: Plasmoid.formFactor === PlasmaCore.Types.Vertical
+    // Tooltips with window thumbnails can be resized by dragging their edges
+    readonly property bool resizable: isWin && Plasmoid.configuration.showToolTips
+    // Sizes when the user started resizing the tooltip, which its windows then follow
+    property var resizeStart: null
     // This number controls the overall size of the window tooltips
-    readonly property int tooltipInstanceMaximumWidth: Kirigami.Units.gridUnit * 16
+    readonly property int tooltipInstanceMaximumWidth: {
+        if (resizeStart) {
+            return resizedInstanceWidth(width);
+        }
+        return resizable && Plasmoid.configuration.toolTipWidth > 0 ? Plasmoid.configuration.toolTipWidth : Kirigami.Units.gridUnit * 16;
+    }
+    readonly property int thumbnailHeight: {
+        if (resizeStart) {
+            return resizedThumbnailHeight(height);
+        }
+        return resizable && Plasmoid.configuration.toolTipThumbnailHeight > 0 ? Plasmoid.configuration.toolTipThumbnailHeight : Kirigami.Units.gridUnit * 8;
+    }

     // These properties are required to make tooltip interactive when there is a player but no window is present.
     readonly property Mpris.PlayerContainer playerData: mpris2Source.playerForLauncherUrl(launcherUrl, pidParent)
@@ -67,6 +82,39 @@ Loader {

     sourceComponent: isGroup ? groupToolTip : singleTooltip

+    // A group tooltip shares the new size among its windows
+    function resizedInstanceWidth(width: real): int {
+        const count = isGroup && !isVerticalPanel ? Math.max(1, windows.length) : 1;
+        const size = resizeStart.instanceWidth + (width - resizeStart.width) / count;
+        return Math.round(Math.max(Kirigami.Units.gridUnit * 10, Math.min(size, Screen.width / 2)));
+    }
+
+    function resizedThumbnailHeight(height: real): int {
+        const count = isGroup && isVerticalPanel ? Math.max(1, windows.length) : 1;
+        const size = resizeStart.thumbnailHeight + (height - resizeStart.height) / count;
+        return Math.round(Math.max(Kirigami.Units.gridUnit * 4, Math.min(size, Screen.height / 2)));
+    }
+
+    Connections {
+        target: toolTipDelegate.parentTask
+
+        function onResizingChanged(): void {
+            toolTipDelegate.resizeStart = toolTipDelegate.parentTask.resizing ? {
+                width: toolTipDelegate.width,
+                height: toolTipDelegate.height,
+                instanceWidth: toolTipDelegate.tooltipInstanceMaximumWidth,
+                thumbnailHeight: toolTipDelegate.thumbnailHeight,
+            } : null;
+        }
+
+        function onResized(size: size): void {
+            if (toolTipDelegate.resizeStart) {
+                Plasmoid.configuration.toolTipWidth = toolTipDelegate.resizedInstanceWidth(size.width);
+                Plasmoid.configuration.toolTipThumbnailHeight = toolTipDelegate.resizedThumbnailHeight(size.height);
+            }
+        }
+    }
+
     Component {
         id: singleTooltip

@@ -149,7 +197,7 @@ Loader {

                 // On Wayland, a tooltip has a significant resizing process, so estimate the size first.
                 readonly property real estimatedWidth: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? 1 : count) * (toolTipDelegate.tooltipInstanceMaximumWidth + Kirigami.Units.gridUnit) - Kirigami.Units.gridUnit
-                readonly property real estimatedHeight: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? count : 1) * (Plasmoid.configuration.showToolTips ? (toolTipDelegate.tooltipInstanceMaximumWidth / 2 + Kirigami.Units.gridUnit) : Kirigami.Units.gridUnit * 2) - Kirigami.Units.gridUnit
+                readonly property real estimatedHeight: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? count : 1) * (Plasmoid.configuration.showToolTips ? (toolTipDelegate.thumbnailHeight + Kirigami.Units.gridUnit) : Kirigami.Units.gridUnit * 2) - Kirigami.Units.gridUnit

                 model: tasksModel

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..67692cf1cc 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -287,7 +287,7 @@ ColumnLayout {
         id: thumbnailSourceItem

         Layout.fillWidth: true
-        Layout.preferredHeight: Kirigami.Units.gridUnit * 8
+        Layout.preferredHeight: toolTipDelegate.thumbnailHeight

         clip: true
         visible: Plasmoid.configuration.showToolTips && toolTipDelegate.isWin
